/**
 * Content format of the `content` field on create (POST only; ignored on PUT, never returned on GET).
 *
 * - `AUTO` (default): behaves like before this field existed - an HTML content file is created only for advanced HTML (non-simple HTML)
 * - `PLAIN`: content is stored as plain text only; no HTML content file is created (HTML input is converted to text)
 * - `HTML`: an HTML content file is always created. Placeholders are replaced only for `HTML` combined with dataType `EMAIL`.
 */
export type TicketProcessContentType = ApiValuedLinkEnum & {
  value?: TicketProcessContentTypeValue;
};

